import SwiftUI
import NavigationBackport

#Preview("Nested replies") {
    PreviewContainer({ pe in
        pe.loadContacts()
        pe.parseMessages(NestedRepliesPreviewData.relayMessages)
        try? pe.context.save()
    }) {
        NBNavigationStack {
            if let rootPost = PreviewFetcher.fetchNRPost(
                NestedRepliesPreviewData.rootPostId
            ) {
                ScrollView {
                    ThreadReplies(nrPost: rootPost)
                        .environment(\.nxViewingContext, [.selectableText, .postReply, .detailPane])
                }
            }
        }
    }
}

